#include <cstdio>
#include <algorithm>
#include <iostream>

#define LL long long

#define ITER(i, a, b) for (int i = a; i <= b; i++)
#define REPEAT(i, a, b) for (int i = a; i >= b; i--)

const int MAX_LIMIT = 1e6 + 1e5, MOD_VALUE = 1e9 + 7;

LL k_value, p_value;
int count;
LL answer;
int visited_flags[MAX_LIMIT];
int stored_vals[MAX_LIMIT];

void adjust(LL &x) { x = (x % MOD_VALUE + MOD_VALUE) % MOD_VALUE; }

void bfs(int start)
{
    ++count;
    int origin = start;
    LL weight = 1;
    do {
        visited_flags[start] = true;
        start = start * k_value % p_value;
        weight = weight * k_value % p_value;
    } while (start != origin);
    adjust(answer *= (weight == 1 ? p_value : 1));
}

void solve()
{
    if (k_value == 0) {
        LL product = 1;
        ITER(i, 1, p_value - 1)
            product = product * p_value % MOD_VALUE;
        printf("%lld\n", product);
        return;
    }
    answer = 1;
    ITER(i, 0, p_value - 1)
        if (visited_flags[i] == 0)
            bfs(i);
    printf("%lld\n", answer);
}

int main()
{
    if (fopen("B.in", "r") != NULL) {
        freopen("B.in", "r", stdin);
        freopen("B.out", "w", stdout);
    }

    scanf("%lld%lld", &p_value, &k_value);
    solve();

    return 0;
}
